const key="companyos_bids";function load(){try{return JSON.parse(localStorage.getItem(key)||"[]")}catch{return[]}}function save(v){localStorage.setItem(key,JSON.stringify(v))}function render(){const bids=load(),list=document.getElementById("bids");const total=bids.reduce((s,b)=>s+Number(b.amount||0),0);document.getElementById("summary").textContent=`${bids.length} bids | Pipeline: $${total.toFixed(2)}`;list.innerHTML="";for(const b of bids){const el=document.createElement("div");el.className="bid";el.textContent=`${b.customer} — ${b.project} — $${Number(b.amount).toFixed(2)} — ${b.status}`;list.appendChild(el)}}document.getElementById("bidForm").addEventListener("submit",e=>{e.preventDefault();const bids=load();bids.push({customer:document.getElementById("customer").value.trim(),project:document.getElementById("project").value.trim(),amount:Number(document.getElementById("amount").value),status:document.getElementById("status").value});save(bids);e.target.reset();render()});render();